    "1111000101101111000101100010011001100000000010110101010000000100",
    "1111000101101111000101100010011001100000000010110101010000000100",
    "0110000000001011010101000000010001100000000010110101010000000100",
    "1111000101101111000101100010011001100000000010110101010000000100",
    "1111000101101111000101100010011001100000000010110101010000000100",
    "1101010110001011110001000111110111010101100010111100010001111101",
    "1001010100110110101010111010101011010101100010111100010001111101",
    "1111000101101111000101100010011011110001011011110001011000100110",
    "1001010100110110101010111010101011110001011011110001011000100110",
    "1001010100110110101010111010101011010101100010111100010001111101",
    "1001010100110110101010111010101011010101100010111100010001111101",
    "1001010100110110101010111010101000001000111100011111000000010010",
    "0101001100111101111001100000010111110001011011110001011000100110",
    "1001010101100111011101101100110010010101011001110111011011001100",
    "1001010101100111011101101100110010010101011001110111011011001100",
    "1001010101100111011101101100110011000101011000100110100110010110",
    "1100000011010001100010000011100111000101011000100110100110010110",
    "1111000101101111000101100010011011110001011011110001011000100110",
    "1111000101101111000101100010011011110001011011110001011000100110",
    "1101010110001011110001000111110111000101011000100110100110010110",
    "1101010110001011110001000111110111000101011000100110100110010110",
    "1101010110001011110001000111110111110001011011110001011000100110",
    "1101010110001011110001000111110111110001011011110001011000100110");
begin
  dut : entity work.regfile port map (clk => s_clk, we => s_we, ra1 => s_ra1, ra2 => s_ra2, wa => s_wa, wd => s_wd, rd1 => s_rd1, rd2 => s_rd2);
  clk_i <= not clk_i after 5 ns when not done else clk_i;
  s_clk <= clk_i;
  process
    variable l : line;
    variable got : std_logic_vector(1 to 64);
    variable errors : natural := 0;
  begin
    for i in stim'range loop
      wait until falling_edge(clk_i);
      wait for 2 ns;
      s_we <= stim(i)(1);
      s_ra1 <= stim(i)(2 to 6);
      s_ra2 <= stim(i)(7 to 11);
      s_wa <= stim(i)(12 to 16);
      s_wd <= stim(i)(17 to 48);
      wait until rising_edge(clk_i);
      wait for 1 ns;
      got(1 to 32) := s_rd1;
      got(33 to 64) := s_rd2;
      for b in got'range loop
        if expv(i)(b) /= '-' and got(b) /= expv(i)(b) then
          errors := errors + 1;
          if errors <= 10 then
            report "MISMATCH vector " & integer'image(i) & " bit " & integer'image(b)
              & " expected " & std_logic'image(expv(i)(b))
              & " got " & std_logic'image(got(b)) severity warning;
          end if;
        end if;
      end loop;
    end loop;
    done <= true;
    assert errors = 0
      report integer'image(errors) & " output bit(s) differ from the golden vectors"
      severity error;
    if errors = 0 then report "GOLDEN_PASS" severity note; end if;
    wait;
  end process;
end architecture;
